const tabId = 248688717;
const nextDataInfo = await browserjs(tabId, () => {
  const script = document.getElementById('__NEXT_DATA__');
  if (!script) return "No next data script";
  const data = JSON.parse(script.textContent);

  // Function to search for keys or strings in the object tree
  function findObjectsWithKey(obj, targetKey) {
    const results = [];
    function recurse(current) {
      if (!current || typeof current !== 'object') return;
      if (Array.isArray(current)) {
        for (const item of current) recurse(item);
      } else {
        if (targetKey in current) {
          results.push(current[targetKey]);
        }
        for (const k of Object.keys(current)) {
          recurse(current[k]);
        }
      }
    }
    recurse(obj);
    return results;
  }

  // Look for onboard activities or similar
  const activitiesMatches = findObjectsWithKey(data, 'onboardActivities')
    .concat(findObjectsWithKey(data, 'activities'))
    .concat(findObjectsWithKey(data, 'obaSection'))
    .concat(findObjectsWithKey(data, 'oba'));

  return {
    activitiesMatches: activitiesMatches.slice(0, 10),
    keysUnderPageProps: Object.keys(data.props?.pageProps || {})
  };
});
console.log(JSON.stringify(nextDataInfo, null, 2));

