const tabId = 248688717;
const allActivitiesFromNextData = await browserjs(tabId, () => {
  const script = document.getElementById('__NEXT_DATA__');
  if (!script) return "No script";
  const data = JSON.parse(script.textContent);

  // Let's traverse data to find all objects with overviewTitle
  const items = [];
  function recurse(node, path = '') {
    if (!node || typeof node !== 'object') return;
    if (node.overviewTitle) {
      items.push({
        path,
        overviewTitle: node.overviewTitle,
        cost: node.costType?.displayName,
        ageRange: node.ageRangeText,
        detailsTitle: node.detailsTitle
      });
    }
    if (Array.isArray(node)) {
      node.forEach((child, idx) => recurse(child, `${path}[${idx}]`));
    } else {
      Object.keys(node).forEach(k => recurse(node[k], `${path}.${k}`));
    }
  }

  recurse(data);
  return items;
});

console.log("Found items count:", allActivitiesFromNextData.length);
console.log("Items:", JSON.stringify(allActivitiesFromNextData, null, 2));

