const tabId = 248688717;
const angularData = await browserjs(tabId, () => {
  if (!window.angular) return "No angular";

  // Find angular element with scope
  const el = document.querySelector('[ng-controller], [ng-repeat], [data-ng-controller], .cgl-listing, .listing-content') || document.querySelector('[ng-app]');
  if (!el) return "No angular element found";

  const scope = window.angular.element(el).scope();
  if (!scope) return "No scope found";

  // Collect scope keys
  const keys = Object.keys(scope).filter(k => !k.startsWith('$'));

  // Check if there are items or results
  const items = scope.results || scope.activities || scope.items || scope.model || scope.data;

  return {
    keys,
    hasItems: !!items,
    sample: items ? (Array.isArray(items) ? items.slice(0, 5) : Object.keys(items)) : null
  };
});
console.log(JSON.stringify(angularData, null, 2));

